  "backgrounds/golden_bloom/midground": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1080\" height=\"1920\" viewBox=\"0 0 1080 1920\">\n    <!-- Tree 1 (Left): trunk grounded to y=1920 -->\n    <path d=\"M85 1920 L85 1400 Q80 1180 98 1020\" stroke=\"#5C3417\" stroke-width=\"12\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path d=\"M90 1220 Q110 1150 125 1160\" stroke=\"#5C3417\" stroke-width=\"8\" fill=\"none\" stroke-linecap=\"round\"/>\n    <!-- Tree 1 Canopies (narrow in SVG for round arcade stretch) -->\n    <path d=\"M60 1100 C45 1030 50 940 85 890 C110 840 145 880 145 950 C155 1010 130 1100 95 1120 C75 1125 65 1115 60 1100 Z\" fill=\"#B45309\" opacity=\".92\"/>\n    <path d=\"M68 1080 C55 1020 60 950 88 910 C108 870 135 900 135 960 C142 1010 122 1080 95 1095 C80 1100 72 1092 68 1080 Z\" fill=\"#F59E0B\" opacity=\".95\"/>\n    <path d=\"M75 1050 C68 1010 72 960 90 930 C104 900 122 920 122 965 C126 1000 112 1050 94 1065 C84 1070 78 1060 75 1050 Z\" fill=\"#FEF08A\" opacity=\".8\"/>\n\n    <!-- Tree 2 (Mid-Left): trunk grounded to y=1920 -->\n    <path d=\"M210 1920 L210 1420 Q205 1240 220 1080\" stroke=\"#5C3417\" stroke-width=\"10\" fill=\"none\" stroke-linecap=\"round\"/>\n    <!-- Tree 2 Canopies -->\n    <path d=\"M190 1140 C175 1080 180 1000 210 960 C232 920 258 950 258 1010 C265 1060 245 1130 218 1150 C202 1155 194 1148 190 1140 Z\" fill=\"#B45309\" opacity=\".88\"/>\n    <path d=\"M196 1120 C184 1070 188 1010 212 975 C230 940 250 965 250 1015 C255 1055 238 1115 218 1130 C206 1135 200 1128 196 1120 Z\" fill=\"#F59E0B\" opacity=\".92\"/>\n\n    <!-- Tree 3 (Right): trunk grounded to y=1920 -->\n    <path d=\"M890 1920 L890 1390 Q895 1190 875 1030\" stroke=\"#5C3417\" stroke-width=\"12\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path d=\"M885 1230 Q865 1160 850 1170\" stroke=\"#5C3417\" stroke-width=\"8\" fill=\"none\" stroke-linecap=\"round\"/>\n    <!-- Tree 3 Canopies -->\n    <path d=\"M840 1110 C825 1040 830 950 865 900 C890 850 925 890 925 960 C935 1020 910 1110 875 1130 C855 1135 845 1125 840 1110 Z\" fill=\"#B45309\" opacity=\".92\"/>\n    <path d=\"M848 1090 C835 1030 840 960 868 920 C888 880 915 910 915 970 C922 1020 902 1090 875 1105 C860 1110 852 1102 848 1090 Z\" fill=\"#F59E0B\" opacity=\".95\"/>\n    <path d=\"M855 1060 C848 1020 852 970 870 940 C884 910 902 930 902 975 C906 1010 892 1060 874 1075 C864 1080 858 1070 855 1060 Z\" fill=\"#FEF08A\" opacity=\".8\"/>\n\n    <!-- Traditional Taiko-bashi Arched Bridge (width ~110px in SVG -> ~420px on screen) -->\n    <!-- Pillars anchored to y=1920 -->\n    <path d=\"M495 1920 L495 1570 M520 1920 L520 1545 M545 1920 L545 1530 M570 1920 L570 1545 M595 1920 L595 1570\" stroke=\"#451A03\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <!-- Vermillion Lacquer Arched Beam -->\n    <path d=\"M475 1630 Q545 1490 615 1630\" stroke=\"#9A3412\" stroke-width=\"16\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path d=\"M478 1626 Q545 1494 612 1626\" stroke=\"#C2410C\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\"/>\n    <!-- Upper Railing -->\n    <path d=\"M482 1595 Q545 1460 608 1595\" stroke=\"#7C2D12\" stroke-width=\"5\" fill=\"none\" stroke-linecap=\"round\"/>\n    <!-- Railing Vertical Posts -->\n    <path d=\"M492 1615 L492 1580 M512 1590 L512 1550 M532 1575 L532 1532 M545 1568 L545 1526 M558 1575 L558 1532 M578 1590 L578 1550 M598 1615 L598 1580\" stroke=\"#7C2D12\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n    <!-- Golden Finials (Giboshi) atop the posts -->\n    <circle cx=\"492\" cy=\"1578\" r=\"3.5\" fill=\"#FBBF24\"/>\n    <circle cx=\"512\" cy=\"1548\" r=\"3.5\" fill=\"#FBBF24\"/>\n    <circle cx=\"532\" cy=\"1530\" r=\"3.8\" fill=\"#FBBF24\"/>\n    <circle cx=\"545\" cy=\"1524\" r=\"4.2\" fill=\"#FBBF24\"/>\n    <circle cx=\"558\" cy=\"1530\" r=\"3.8\" fill=\"#FBBF24\"/>\n    <circle cx=\"578\" cy=\"1548\" r=\"3.5\" fill=\"#FBBF24\"/>\n    <circle cx=\"598\" cy=\"1578\" r=\"3.5\" fill=\"#FBBF24\"/>\n    <!-- Stone Lantern with Warm Glowing Core near bridge -->\n    <path d=\"M455 1920 L455 1630 L450 1625 L460 1625 Z\" fill=\"#5C3417\"/>\n    <rect x=\"450\" y=\"1612\" width=\"10\" height=\"12\" rx=\"2\" fill=\"#FEF9C3\" opacity=\".9\"/>\n    <path d=\"M447 1612 L463 1612 L455 1604 Z\" fill=\"#5C3417\"/>\n</svg>",
